sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

	var requestBody = request.body.data;
	var noteSysId = requestBody.note_sys_id;
	var incidentSysId = requestBody.incident_sys_id;
	var newWorkNote = requestBody.work_note;

	if (!noteSysId || !incidentSysId || !newWorkNote) {
		response.setStatus(400);
		response.setBody({ result: 'Missing required fields: note_sys_id, incident_sys_id, or work_note' });
		return;
	}

	var importGR = new GlideRecord('x_xurre_imr_u_import_work_note');
	importGR.initialize();
	importGR.setValue('operation', 'update_work_note');
	importGR.setValue('incident_sys_id', incidentSysId);
	importGR.setValue('note_sys_id', noteSysId);
	importGR.setValue('work_note', newWorkNote);
	var importSysId = importGR.insert();

	importGR.get(importSysId);
	var resultStatus = importGR.getValue('result_status');
	var resultMessage = importGR.getValue('result_message');

	if (resultStatus !== 'success') {
		response.setStatus(400);
		response.setBody({ result: resultMessage });
		return;
	}

	response.setStatus(200);
	response.setBody({
		message: 'Work note updated successfully',
		sys_id: noteSysId
	});
})(request, response);
